import{z as i,x as o,o as e,c as d,q as t,j as B,D as A,d as r,s,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"求和顺序","description":"","frontmatter":{"title":"求和顺序","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/summation-order.md","filePath":"cs/summation-order.md","lastUpdated":1791063341000}'),p={name:"cs/summation-order.md"};function m(u,a,h,D,f,c){const n=o("Mermaid");return e(),d("div",null,[a[2]||(a[2]=t('<h1 id="求和顺序" tabindex="-1">求和顺序 <a class="header-anchor" href="#求和顺序" aria-label="Permalink to &quot;求和顺序&quot;">​</a></h1><div class="epigraph"><p>实数加法可结合；浮点加法每步舍入，先加谁等于选择哪一次差被丢掉——顺序是算法，不是括号游戏。</p><footer>—— 据 Higham, Accuracy and Stability of Numerical Algorithms；Trefethen and Bau, Numerical Linear Algebra 整理</footer></div><p>上一课<a href="/cs/catastrophic-cancellation">消去与灾难抵消</a>说明近量相减会吃掉有效位。本课不重写有理化，也不从并行归约树的硬件另起。缺口是：许多项相加时，每步都是一次 \\(\\mathrm{fl}(+)\\)，<strong>结合律失败之后，顺序怎样改变后向误差，补偿算法补的是哪一块</strong>。这是「浮点之后」课序的末课，下一课转入线性方程。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(\\sum x_i\\) 在实数里与括号无关。机器上递归 \\(s_{k}=\\mathrm{fl}(s_{k-1}+x_k)\\) 把每步 \\(\\delta\\) 乘进后续所有加法。大数先入再加一串小数，小数可能对 \\(s\\) 毫无贡献（吸收）；异号近量交错则反复抵消。缺口因此不是「求和会有误差」，而是<strong>顺序与分组是算法选择</strong>：它们改变误差传播路径，有时也制造或避免抵消。</p><p>条件数：求和问题相对 \\(\\sum|x_i|\\) 的条件大约是 \\(\\sum|x_i|/|\\sum x_i|\\)，异号时病态。算法再差，也不能突破这个下界。本课在良态与病态之间都给可做的事：排序、成对、补偿。</p><p><span class="marginnote">代个数感受量级：机器精度 \\(u\\approx 1.1\\times10^{-16}\\)（双精度），\\(n=10^7\\) 个数递归相加，后向误差约 \\(nu\\approx 10^{-9}\\) 量级；换成 Kahan 补偿，误差压到 \\(u\\) 附近，缩了七个数量级——同一份输入，只换了加法顺序与记账方式。</span></p><h3 id="更高精度累加器不是「换了问题」" tabindex="-1">更高精度累加器不是「换了问题」 <a class="header-anchor" href="#更高精度累加器不是「换了问题」" aria-label="Permalink to &quot;更高精度累加器不是「换了问题」&quot;">​</a></h3><p>用更宽寄存器做 \\(s\\) 再舍入回工作精度，是在减少算法注入，问题 \\(f\\) 仍是原来的和。这与改写成别的数学式不同。Kahan 补偿在工作精度里多记一项校正，目标同样是压低后向误差，不是把条件数变小。把补偿当成「数学上改了定义」，会与下一课主元选择的动机搅在一起。</p><p><span class="marginnote">Higham 专章讨论 summation。Trefethen and Bau 用浮点加法的非结合当作贯穿全书的提醒。本课不把所有并行 reduction 的确定性保证写完。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>递归求和：后向误差 \\(O(nu)\\)，常数随顺序变。按绝对值递增加，往往减少吸收。成对（二叉树）把深度降到 \\(\\log n\\)，界更好且利于并行。Kahan：维护校正项 \\(c\\)，每次把丢掉的低位补回——在典型硬件上把有效误差从 \\(O(nu)\\) 降到接近 \\(O(u)\\)。排序与补偿可以组合，病态和仍可能不准。</p>',12)),(e(),B(l,null,{default:A(()=>[s(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%90%84%E9%A1%B9%20x_i%22%5D%20--%3E%20REC%5B%22%E9%80%92%E5%BD%92%E5%8A%A0%EF%BC%9A%E6%B7%B1%E5%BA%A6%20n%22%5D%0A%20%20X%20--%3E%20PAIR%5B%22%E6%88%90%E5%AF%B9%E5%8A%A0%EF%BC%9A%E6%B7%B1%E5%BA%A6%20log%20n%22%5D%0A%20%20X%20--%3E%20KAHAN%5B%22%E8%A1%A5%E5%81%BF%E6%B1%82%E5%92%8C%22%5D%0A%20%20REC%20--%3E%20E1%5B%22%E5%90%8E%E5%90%91%E8%AF%AF%E5%B7%AE%E7%BA%A6%20n%20u%22%5D%0A%20%20PAIR%20--%3E%20E2%5B%22%E5%90%8E%E5%90%91%E8%AF%AF%E5%B7%AE%E7%BA%A6%20log%20n%20%E4%B9%98%20u%22%5D%0A%20%20KAHAN%20--%3E%20E3%5B%22%E5%90%8E%E5%90%91%E8%AF%AF%E5%B7%AE%E6%8E%A5%E8%BF%91%20u%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"内积是带乘法的求和，顺序与是否 FMA 同样改变 \\(\\delta\\) 的个数。BLAS 的具体顺序是实现细节；分析时按最坏或按其后向保证来用。",-1)),a[4]||(a[4]=E("p",null,"内积、多项式 Horner 求值、矩阵行和都是求和的变体：Horner 把顺序钉成嵌套乘加，通常比展开成高次幂再加更稳，因为它改变了 \\(f\\) 的求值路径。补偿可以嵌进内积，但 BLAS 为了速度常常只用递归加。分析时把实现宣称的后向保证当规格，而不是假定「数学上的和」。下一课消元里的更新是许多次 saxpy，顺序由主元给定，误差图像从求和换成秩一更新。",-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"每次加法把较小操作数的低位对齐后丢掉。顺序决定谁当「较小」：累加器变大后，后来的项更容易被吸收。树状分组让中间和的量级更接近，减少这种不对等。补偿显式把丢掉的尾数留到下一步——等于多保存一点部分和的信息。这些都不改变 754 的位型，只改变舍入发生的位置与次数。",-1)),a[7]||(a[7]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：把累加器想成一个固定宽度的托盘。先倒进一块大石头，再倒细沙，细沙全从边缘漏掉——这就是「大数吸收小数」。成对求和相当于先把小石头归成中石头再上托盘，每次对齐时漏掉的都少。")],-1)),a[8]||(a[8]=E("p",null,"把「吸收」一步步拆开看，顺序问题就有了着落。",-1)),(e(),B(l,null,{default:A(()=>[s(n,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20BIG%5B%22%E7%B4%AF%E5%8A%A0%E5%99%A8%20s%20%E5%B7%B2%E5%BE%88%E5%A4%A7%22%5D%20--%3E%20AL%5B%22%E5%8A%A0%E5%85%A5%E5%B0%8F%E9%A1%B9%20x%EF%BC%9A%E5%AF%B9%E9%BD%90%E6%8C%87%E6%95%B0%22%5D%0A%20%20AL%20--%3E%20SH%5B%22x%20%E7%9A%84%E4%BD%8E%E4%BD%8D%E8%A2%AB%E7%A7%BB%E5%87%BA%E6%9C%89%E6%95%88%E4%BD%8D%22%5D%0A%20%20SH%20--%3E%20RN%5B%22%E8%88%8D%E5%85%A5%EF%BC%9A%E4%B8%A2%E6%8E%89%E7%A7%BB%E5%87%BA%E9%83%A8%E5%88%86%22%5D%0A%20%20RN%20--%3E%20ABS%5B%22s%20%E7%BA%B9%E4%B8%9D%E4%B8%8D%E5%8A%A8%20%3D%20%E8%A2%AB%E5%90%B8%E6%94%B6%22%5D%0A%20%20PAIR%5B%22%E6%88%90%E5%AF%B9%E5%8A%A0%EF%BC%9A%E4%B8%AD%E9%97%B4%E5%92%8C%E9%87%8F%E7%BA%A7%E6%8E%A5%E8%BF%91%22%5D%20-.-%3E%20LESS%5B%22%E5%AF%B9%E9%BD%90%E4%B8%A2%E7%9A%84%E4%BD%8D%E6%95%B0%E5%B0%91%22%5D%0A%20%20KAHAN%5B%22Kahan%EF%BC%9A%E6%A0%A1%E6%AD%A3%E9%A1%B9%E8%AE%B0%E4%B8%8B%E4%B8%A2%E7%9A%84%E5%B0%BE%E6%95%B0%22%5D%20-.-%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E6%AD%A5%E8%A1%A5%E5%9B%9E%E6%9D%A5%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=t('<p><span class="marginnote">初学者容易把 Kahan 补偿理解成「偷偷用了更高精度」。实际上它全程在工作精度内运算：每步把对齐时丢掉的尾数记进校正项 \\(c\\)，下轮加回去——丢掉的信息被显式记账，而不是换个宽寄存器。</span></p><p>并行规约树的形状也是顺序：同一组数，不同线程划分会得到差几个 \\(u\\) 的结果。需要位对位复现时，必须固定树或改用高精度累加，而不能只固定源码里的 <code>for</code> 循环——编译器也可能再结合。Kahan 的校正项本身是浮点，极端动态范围下仍会丢。对符号相同、量级可比的项，递归和已经够用；对异号或跨很多个数量级的项，先问条件数，再决定是否补偿。线性代数的消元把「选哪一行」当成同一类顺序问题，只是对象从加数换成了行。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证并行归约的位对位可复现，那是实现与规约树的契约。下一课<a href="/cs/gaussian-pivoting">高斯消元与主元</a>把「顺序」换成行交换，对象从求和换成消去。后课默认：浮点求和不可结合；顺序与补偿属于算法；和的条件数仍由数据符号结构决定。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>浮点加法不结合；顺序改变吸收与抵消路径。</li><li>递归和后向误差常 \\(O(nu)\\)；成对与 Kahan 压低算法注入。</li><li>异号求和可以病态，补偿救不了条件数。</li><li>下一课把稳定性问题接到线性消去。</li><li>出处：Higham；Trefethen and Bau。</li></ul>',6))])}const x=i(p,[["render",m]]);export{g as __pageData,x as default};
